// Cyclomatic-complexity tiers (atoms/code/decomposition.md). `complexity` reports
// when a function EXCEEDS the threshold: soft=4 warns at >4, hard=5 errors at >5.
// The hard tier is applied by the commit gate, not here.
export const COMPLEXITY_SOFT = 4;
export const COMPLEXITY_HARD = 5;

// functional-style.md + immutability.md: imperative constructs banned structurally.
const NO_IMPERATIVE_SYNTAX = [
  { selector: 'ForStatement', message: 'No loops — use .map/.filter/.reduce/.find (functional-style.md).' },
  { selector: 'ForInStatement', message: 'No loops — use Object.entries + .map (functional-style.md).' },
  { selector: 'ForOfStatement', message: 'No loops — use .map/.filter/.reduce/.find (functional-style.md).' },
  { selector: 'WhileStatement', message: 'No loops — use recursion or array methods (functional-style.md).' },
  { selector: 'DoWhileStatement', message: 'No loops — use recursion or array methods (functional-style.md).' },
  { selector: "VariableDeclaration[kind='let']", message: 'Use const — never let (functional-style.md).' },
  { selector: 'ClassDeclaration', message: 'No classes for business logic — use functions + types (functional-style.md).' },
  { selector: 'ExportDefaultDeclaration', message: 'No default exports — use named exports (TYPESCRIPT.md).' },
];

export const projectRules = {
  // decomposition.md
  complexity: ['warn', COMPLEXITY_SOFT],
  'max-params': ['warn', 3],
  'max-depth': ['warn', 3],
  'max-lines-per-function': ['warn', { max: 20, skipBlankLines: true, skipComments: true }],
  // functional-style.md / immutability.md
  'no-var': 'error',
  'prefer-const': 'error',
  'no-restricted-syntax': ['error', ...NO_IMPERATIVE_SYNTAX],
  // strict-typing.md
  '@typescript-eslint/no-explicit-any': 'error',
  // Honor the `_`-prefix "intentionally unused" convention (purely permissive).
  '@typescript-eslint/no-unused-vars': [
    'error',
    { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
  ],
  // Public API only. `explicit-function-return-type` also demanded an annotation on
  // every local arrow helper, where the inferred type is right there in the body and
  // the annotation is transcription. A module BOUNDARY is where inference drift
  // actually costs something, so that is where the rule now applies.
  '@typescript-eslint/explicit-module-boundary-types': 'warn',
  '@typescript-eslint/consistent-type-imports': 'warn',
  // naming-constants.md — ON for production code, OFF for tests (the test block
  // below). An unnamed constant in a shipped code path is the debt this catches;
  // a literal in an assertion IS the specification.
  //
  // `ignore` carries the bases that are self-describing wherever they appear, and
  // ONLY those: 1024 (byte-size arithmetic, `64 * 1024 * 1024`), 100 (percent and
  // 2-dp rounding), 60 (time). Naming those would obscure, not explain. Everything
  // else — exit codes, HTTP statuses, thresholds, widths — still reports.
  'no-magic-numbers': [
    'warn',
    { ignore: [-1, 0, 1, 2, 60, 100, 1024], ignoreArrayIndexes: true, ignoreDefaultValues: true, enforceConst: true },
  ],
};

